export function render(container) {
  const app = document.createElement('div');
  app.className = 'app';

  const title = document.createElement('h1');
  title.textContent = 'Password Generator';
  app.appendChild(title);

  const strengthSlider = document.createElement('input');
  strengthSlider.type = 'range';
  strengthSlider.min = 1;
  strengthSlider.max = 5;
  strengthSlider.value = 3;
  strengthSlider.onchange = () => setStrength(parseInt(strengthSlider.value));
  app.appendChild(strengthSlider);

  const lengthSlider = document.createElement('input');
  lengthSlider.type = 'range';
  lengthSlider.min = 6;
  lengthSlider.max = 20;
  lengthSlider.value = 12;
  lengthSlider.onchange = () => setLength(parseInt(lengthSlider.value));
  app.appendChild(lengthSlider);

  const generatedPassword = document.createElement('span');
  generatedPassword.textContent = 'Generated Password: ';
  app.appendChild(generatedPassword);

  const copyBtn = document.createElement('button');
  copyBtn.className = 'btn';
  copyBtn.textContent = 'Copy Password';
  copyBtn.onclick = () => copyPassword();
  app.appendChild(copyBtn);

  const generateBtn = document.createElement('button');
  generateBtn.className = 'btn';
  generateBtn.textContent = 'Generate Password';
  generateBtn.onclick = () => generatePassword();
  app.appendChild(generateBtn);

  container.appendChild(app);
}

function generatePassword() {
  const password = generatePassword();
  generatedPassword.textContent = password;
}

function copyPassword() {
  const password = generatedPassword.textContent;
  navigator.clipboard.writeText(password).then(() => {
    console.log('Password copied to clipboard');
  }).catch(err => {
    console.error('Failed to copy password: ', err);
  });
}

function setStrength(strength) {
  // Update password strength indicator
  const strengthBar = document.getElementById('strength-bar');
  if (strengthBar) {
    strengthBar.style.width = `${strength * 10}%`;
  }
}

function setLength(length) {
  // Update password length indicator
  const lengthBar = document.getElementById('length-bar');
  if (lengthBar) {
    lengthBar.style.width = `${length * 5}%`;
  }
}
